def word_frequency(text: str) -> dict[str, int]:
    import string
    frequencies: dict[str, int] = {}
    for word in text.split():
        word = word.strip(string.punctuation).lower()
        if word:
            frequencies[word] = frequencies.get(word, 0) + 1
    return frequencies
